const isFriend = `-- name: IsFriend :one
SELECT EXISTS(
    SELECT 1 FROM friends 
    WHERE (user_id_1 = CASE WHEN $1 < $2 THEN $1 ELSE $2 END 
       AND user_id_2 = CASE WHEN $1 < $2 THEN $2 ELSE $1 END)
) AS is_friend
`

type IsFriendParams struct {
	Column1 interface{} `json:"column_1"`
	Column2 interface{} `json:"column_2"`
}

// 检查是否是好友
func (q *Queries) IsFriend(ctx context.Context, arg IsFriendParams) (bool, error) {
	row := q.queryRow(ctx, q.isFriendStmt, isFriend, arg.Column1, arg.Column2)
	var is_friend bool
	err := row.Scan(&is_friend)
	return is_friend, err
}

const rejectFriendRequest = `-- name: RejectFriendRequest :one
UPDATE friend_request 
SET 
    status = 'rejected',
    handled_at = NOW()
WHERE request_id = $1 AND to_user_id = $2 AND status = 'pending'
RETURNING 
    request_id,
    from_user_id,
    to_user_id,
    message,
    status,
    createtime,
    handled_at
`

type RejectFriendRequestParams struct {
	RequestID string `json:"request_id"`
	ToUserID  string `json:"to_user_id"`
}

// 拒绝好友请求 POST /friends/request/:requestId/handle
func (q *Queries) RejectFriendRequest(ctx context.Context, arg RejectFriendRequestParams) (FriendRequest, error) {
	row := q.queryRow(ctx, q.rejectFriendRequestStmt, rejectFriendRequest, arg.RequestID, arg.ToUserID)
	var i FriendRequest
	err := row.Scan(
		&i.RequestID,
		&i.FromUserID,
		&i.ToUserID,
		&i.Message,
		&i.Status,
		&i.Createtime,
		&i.HandledAt,
	)
	return i, err
}

const searchFriends = `-- name: SearchFriends :many
SELECT 
    CASE WHEN f.user_id_1 = $1 THEN f.user_id_2 ELSE f.user_id_1 END AS friend_id,
    f.established_at AS friend_since,
    u.username,
    u.nickname,
    u.avatar_url,
    u.bio,
    u.online_status
FROM friends f
JOIN users u ON (CASE WHEN f.user_id_1 = $1 THEN f.user_id_2 ELSE f.user_id_1 END) = u.user_id
WHERE (f.user_id_1 = $1 OR f.user_id_2 = $1)
    AND u.account_status = 'active'
    AND (
        u.username ILIKE '%' || $2 || '%' 
        OR u.nickname ILIKE '%' || $2 || '%'
    )
ORDER BY u.online_status DESC, f.established_at DESC
LIMIT $3 OFFSET $4
`

type SearchFriendsParams struct {
	UserID1 string         `json:"user_id_1"`
	Column2 sql.NullString `json:"column_2"`
	Limit   int32          `json:"limit"`
	Offset  int32          `json:"offset"`
}

type SearchFriendsRow struct {
	FriendID     interface{}          `json:"friend_id"`
	FriendSince  time.Time            `json:"friend_since"`
	Username     string               `json:"username"`
	Nickname     sql.NullString       `json:"nickname"`
	AvatarUrl    sql.NullString       `json:"avatar_url"`
	Bio          sql.NullString       `json:"bio"`
	OnlineStatus NullUserOnlineStatus `json:"online_status"`
}

// 搜索好友
func (q *Queries) SearchFriends(ctx context.Context, arg SearchFriendsParams) ([]SearchFriendsRow, error) {
	rows, err := q.query(ctx, q.searchFriendsStmt, searchFriends,
		arg.UserID1,
		arg.Column2,
		arg.Limit,
		arg.Offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchFriendsRow{}
	for rows.Next() {
		var i SearchFriendsRow
		if err := rows.Scan(
			&i.FriendID,
			&i.FriendSince,
			&i.Username,
			&i.Nickname,
			&i.AvatarUrl,
			&i.Bio,
			&i.OnlineStatus,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
